"""One todo item and the line that stands for it in the todo file."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass
class Item:
    """A todo item: its text and whether it is done."""

    text: str
    done: bool = False


def parse_line(line: str) -> Item:
    """Parse one line of the todo file, such as '[ ] buy milk' or '[x] pay rent'."""
    return Item(text=line[4:].rstrip("\n"), done=line.startswith("[x]"))


def format_line(item: Item) -> str:
    """The line written to the todo file for item."""
    return f"[{'x' if item.done else ' '}] {item.text}"


def count_open(items: list[Item]) -> int:
    """How many of the items are not done yet."""
    return sum(1 for item in items if not item.done)

